// The chat page polls this so a scheduled task's answer can find its way back
// into the conversation. It reads finished runs and nothing else: no agent, no
// model call, nothing that costs money.
const rows = $input.all().map((item) => item.json).filter((row) => row && row.scheduleId);
const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
// Old enough and it is not news: the owner has moved on, and an unprompted
// read-out of yesterday's task is noise. They can still ask for it.
const FRESH_MINUTES = 12 * 60;

const runs = rows
  .filter((row) => String(row.status ?? '') === 'ok')
  .map((row) => ({
    scheduleId: String(row.scheduleId ?? ''),
    name: String(row.name ?? '').slice(0, 120),
    agentId: String(row.agentId ?? ''),
    ranAt: String(row.ranAt ?? ''),
    minutesAgo: minutesSince(row.ranAt),
  }))
  .filter((run) => run.minutesAgo !== null && run.minutesAgo <= FRESH_MINUTES)
  .sort((a, b) => a.minutesAgo - b.minutesAgo)
  .slice(0, 10);

// The reply itself is deliberately absent. This endpoint carries no passcode,
// so it says which task finished and when, and the agent — which does sit
// behind one — is what reads the answer out.
return [{ json: { schemaVersion: 1, runs } }];
